  private static Object noticeUi(Object state, Object events, boolean local, boolean paused, boolean animating) throws Exception {
    Class<?> ui = Class.forName("pt.tiago.neonline.game.GameUiState");
    for(Constructor<?> constructor : ui.getConstructors()) {
      Class<?>[] types = constructor.getParameterTypes();
      if(types.length!=30 || !types[29].getName().equals("kotlin.jvm.internal.DefaultConstructorMarker")) continue;
      Object[] args = new Object[30];
      for(int i=0;i<28;i++) {
        if(types[i]==boolean.class) args[i]=false;
        else if(types[i]==int.class) args[i]=0;
        else if(types[i]==long.class) args[i]=0L;
      }
      args[0]=state; args[1]=local; args[2]=events; args[4]=paused; args[21]=animating;
      args[28]=~((1<<0)|(1<<1)|(1<<2)|(1<<4)|(1<<21));
      return constructor.newInstance(args);
    }
    throw new IllegalStateException("GameUiState constructor changed; update notice probe");
  }
